changeSet.sql:

IF (OBJECT_ID('DF_Report_ReportType') IS NOT NULL)
begin
		ALTER TABLE [dbo].[Report] DROP CONSTRAINT DF_Report_ReportType;
		ALTER TABLE [dbo].[Report] ALTER COLUMN ReportType [int];
end

begin
declare @iteration int, @itearationMax int;
set @iteration = 0; select @itearationMax = max(cnt) from ( select ( select count(*) from OPENJSON(rtrr.definition, '$.When') with ( FieldTypeid int '$.FieldTypeID', Value NVARCHAR(max) '$.Value' ) as summary inner join FieldType ft on ft.id = summary.FieldTypeid where ft.Type = 'Lookup' and isnumeric(summary.value) <> 1 ) as cnt from ResponsibilityTypeRelationRule rtrr ) cntSel;
While (@iteration < @itearationMax) begin update rtrr set rtrr.Definition = JSON_MODIFY(rtrr.definition, concat('$.When[', j1.[key], '].Value') COLLATE SQL_Latin1_General_CP1_CI_AS, flv.value) ,rtrr.UpdatedOn = getdate() from ResponsibilityTypeRelationRule as rtrr cross apply OPENJSON(rtrr.definition, '$.When') j1 cross apply OPENJSON(j1.[value], '$') with ( FieldTypeid int '$.FieldTypeID', Value NVARCHAR(max) '$.Value' ) as summary inner join FieldType ft on ft.id = summary.FieldTypeid cross apply (select top 1 value from FieldLookupValue flv where flv.FieldTypeID = ft.id and summary.value = flv.text)flv(value) where ft.Type = 'Lookup' and isnumeric(summary.value) <> 1;
set @iteration = @iteration+1; end;
set @iteration = 0; select @itearationMax = max(cnt) from ( select ( select count(*) from OPENJSON(rtrr.definition, '$.Then.Conditions') with ( FieldTypeid int '$.FieldTypeID', Value NVARCHAR(max) '$.Value' ) as summary inner join FieldType ft on ft.id = summary.FieldTypeid where ft.Type = 'Lookup' and isnumeric(summary.value) <> 1 ) as cnt from ResponsibilityTypeRelationRule rtrr ) cntSel;
While (@iteration < @itearationMax) begin update rtrr set rtrr.Definition = JSON_MODIFY(rtrr.definition, concat('$.Then.Conditions[', j1.[key], '].Value') COLLATE SQL_Latin1_General_CP1_CI_AS, flv.value) ,rtrr.UpdatedOn = getdate() from ResponsibilityTypeRelationRule as rtrr cross apply OPENJSON(rtrr.definition, '$.Then.Conditions') j1 cross apply OPENJSON(j1.[value], '$') with ( FieldTypeid int '$.FieldTypeID', Value NVARCHAR(max) '$.Value' ) as summary inner join FieldType ft on ft.id = summary.FieldTypeid cross apply (select top 1 value from FieldLookupValue flv where flv.FieldTypeID = ft.id and summary.value = flv.text)flv(value) where ft.Type = 'Lookup' and isnumeric(summary.value) <> 1;
set @iteration = @iteration+1; end;
end


if exists (select * from [INFORMATION_SCHEMA].[COLUMNS] where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'Issue' and COLUMN_NAME = 'Object')
	and exists(select * from [INFORMATION_SCHEMA].[COLUMNS] where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'Issue' and COLUMN_NAME = 'AssetID')
begin

	update	T
	set		T.AssetID = A.ID,
			T.AssetTypeID = A.AssetTypeID
	from	[Issue] T inner join Asset A on A.Object = T.Object and A.ObjectId = T.ObjectID
	where   T.AssetID is null;

	update	T
	set		T.AssetTypeID = AT.ID
	from	[Issue] T inner join AssetType AT on AT.Object = T.ObjectType and AT.ObjectID = T.ObjectTypeID
	where	T.AssetTypeID is null;

	alter table [dbo].[Issue] drop column [Object];
	alter table [dbo].[Issue] drop column [ObjectID];
	alter table [dbo].[Issue] drop column [ObjectType];
	alter table [dbo].[Issue] drop column [ObjectTypeID];

end


INSERT INTO [queue].[task] (Action, Custom, Date, Object, ObjectID)
SELECT 'QueueRebuild', 'SearchIndex', DATEADD(hour, 3, getdate()), 'User', 0;

INSERT INTO [queue].[task] (Action, Custom, Date, Object, ObjectID)
SELECT 'QueueRebuild', 'SearchIndex', DATEADD(hour, 3, getdate()), 'ReferenceItemType', 0;

IF EXISTS (SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = 'analytics' AND TABLE_NAME = 'Ip') BEGIN set identity_insert usage.[Ip] on
MERGE usage.[Ip] AS t USING analytics.[Ip] AS s ON s.Value = t.Value WHEN NOT MATCHED BY target THEN INSERT (Id,Value) VALUES (s.ID,s.Value);
set identity_insert usage.[Ip] off END

declare @FieldTypeID int;
select top 1 @FieldTypeID = FT.ID from assettype ATT inner join FieldType FT on ATT.ID = FT.AssetTypeID where ATT.Class = 9 and ATT.Name = 'Rule Dimension' and ft.Type = 'Html' and ft.name ='Description';
if (@FieldTypeID is not null) begin Update FT set Type = 'Text' From fieldType FT where FT.ID = @FieldTypeID;
Update F set [Value]= [reporting].[StripHTML]( F.[Value]), [Formattedvalue] = [reporting].[StripHTML]( F.[Formattedvalue]) From Field F where F.FieldTypeID = @FieldTypeID; end


delete from [dbo].[HelpResource] where [Url] = 'Default.htm#c-user-guide/user-guide.htm%3FTocPath%3DUser%2520guide%7C_____0' and [isSystem] = 1;
delete from [dbo].[HelpResource] where [Url] = 'Default.htm#d-admin/admin-intro.htm%3FTocPath%3DAdministration%2520guide%7C_____0' and [isSystem] = 1;
delete from [dbo].[HelpResource] where [Url] = 'Default.htm#b-release-notes/whats-new.htm%3FTocPath%3DWhat' and [isSystem] = 1;


delete from [dbo].[HelpResource] where [Url] = 'Data360-Govern-Help/User-guide' and [isSystem] = 1;
delete from [dbo].[HelpResource] where [Url] = 'Data360-Govern-Help/Administration' and [isSystem] = 1;
delete from [dbo].[HelpResource] where [Url] = 'Data360-Govern-Release-Notes/Latest-release' and [isSystem] = 1;
